action.command:
awk '
/^[[:space:]]*\[/ {
  line=$0; gsub(/^[[:space:]]*\[|\][[:space:]]*$/, "", line); print "[" line "]"; next
}
/^[[:space:]]*[A-Za-z0-9_.-]+[[:space:]]*=/ {
  line=$0; sub(/^[[:space:]]*/, "", line); sub(/[[:space:]]*=.*$/, "", line); print "  " line
}
' app_config.ini

